window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":1.885},{"id":"o02","text":"Do not hang up.","at":4.17,"t0":2.085,"t1":3.165},{"id":"n01","text":"Would you fall for this?","at":6.93,"t0":3.465,"t1":4.635},{"id":"n02","text":"Then find the three mistakes on this call.","at":11.17,"t0":5.585,"t1":7.595},{"id":"o03","text":"Again. A parcel in your name.","at":15.69,"t0":7.845,"t1":9.82},{"id":"o05","text":"Your pension account is frozen.","at":22.04,"t0":11.02,"t1":13.045},{"id":"o06","text":"Declare your gold, madam.","at":26.53,"t0":13.265,"t1":14.935},{"id":"o08","text":"Tell anyone, and they are arrested too.","at":30.37,"t0":15.185,"t1":17.345},{"id":"o09","text":"That is my team.","at":38.39,"t0":19.195,"t1":20.505},{"id":"n03","text":"You just looked at your door, didn't you?","at":41.61,"t0":20.805,"t1":22.455},{"id":"n04","text":"Even though his badge can't spell police.","at":45.21,"t0":22.605,"t1":24.665},{"id":"n05","text":"And even if it could, there's no such thing as a digital arrest.","at":49.63,"t0":24.815,"t1":28.145},{"id":"n06","text":"You only know that because somebody told you.","at":56.89,"t0":28.445,"t1":30.58},{"id":"n07","text":"Nobody told your mother.","at":61.66,"t0":30.83,"t1":32.125},{"id":"n08","text":"This was never your call.","at":65.95,"t0":32.975,"t1":34.385},{"id":"n09","text":"While you hunted for mistakes, she took off her gold bangles, trying to prove she'd done nothing wrong.","at":70.67,"t0":35.335,"t1":40.53},{"id":"x01","text":"Ma?","at":86.26,"t0":43.13,"t1":43.92},{"id":"n12","text":"That's not his team, that's you, asking if she's okay.","at":88.54,"t0":44.27,"t1":47.29},{"id":"o11","text":"Tell anyone, and they are arrested too.","at":95.28,"t0":47.64,"t1":49.765},{"id":"m01","text":"I'm fine, beta.","at":100.53,"t0":50.265,"t1":51.46},{"id":"m02","text":"You eat.","at":103.62,"t0":51.81,"t1":52.63},{"id":"n14","text":"She hadn't eaten in twenty-six hours, and you went and ate.","at":111.76,"t0":55.88,"t1":58.98},{"id":"n15","text":"The third mistake is yours.","at":120.66,"t0":60.33,"t1":61.855},{"id":"n16","text":"You'd never fall for this.","at":124.21,"t0":62.105,"t1":63.515},{"id":"n17","text":"But you'd fall for \"I'm fine.\"","at":127.53,"t0":63.765,"t1":65.195},{"id":"n18","text":"Your real mother has a phone.","at":132.09,"t0":66.045,"t1":67.545},{"id":"n19","text":"Has anybody told her?","at":135.79,"t0":67.895,"t1":69.275}];
